// When messages may go.
// Barks (TH-BRK): who hears when something needs a person, and the hours they are barked at. The engine routes; this only edits its rules.
const BARK_ROWS: [string, string, string][] = [["document", "A document to check", "The sniff test was not sure"], ["question", "A client question", "Or a reply Tallyhound could not place"], ["says_none", "A client has none", "Says they don't have a document"], ["gone_quiet", "Gone quiet", "No reply after the last reminder"], ["cant_reach", "Can't reach a client", "No working number or address is left"], ["change_noted", "A change noted", "A reply that may change the checklist"], ["call", "A call to make", "Planned from the review queue"], ["output_check", "A blocked message", "Failed the safety check"]];
function BarksTab() {
  const { T, act, toast } = useFirm(), s = T.S, rules: Record<string, { target?: string; user_ids?: string[] }> = s.firm.barkRules || {}, h = T.staffHours(), staff: Row[] = s.users.filter((u: Row) => u.role !== "read_only" && !u.support), desk = staff.filter((u) => (u.duties || []).includes("front_desk"));
  const [naming, setNaming] = useState<string | null>(null);   // a kind set to named people that has nobody named yet is not saved until someone is
  const save = (next: typeof rules) => void act("setBarkRules", next).then((r) => toast(r ? String(r) + "." : "Saved. The hound barks at the right people from now on."), () => {});
  const target = (k: string) => (naming === k ? "named_users" : (rules[k] && rules[k]!.target) || T.BARK_DEFAULT[k] || "client_preparer"), ids = (k: string) => (rules[k] && rules[k]!.user_ids) || [];
  const pick = (k: string, t: string) => { if (t === "named_users") return setNaming(k); setNaming(null); save({ ...rules, [k]: { target: t } }); }, name = (k: string, list: string[]) => { if (!list.length) { setNaming(k); const next = { ...rules }; delete next[k]; return save(next); } setNaming(null); save({ ...rules, [k]: { target: "named_users", user_ids: list } }); };
  const hours = (a: number, b: number) => void act("setStaffHours", a, b).then((r) => toast(r ? String(r) : "Saved."), () => {});
  const TARGET: [string, string][] = [["client_preparer", "The client's preparer"], ["front_desk", "Office manager"], ["owners", "Owners"], ["named_users", "People you name"]];
  return <div className="col" style={{ gap: 16 }}>
    <div className="card"><div className="hd"><h2>Who hears the barks</h2></div><div className="bd"><p className="small muted">When something needs a person, Tallyhound barks: an alert to the right member of your team, pointing to the review queue. Choose who hears each kind. If the choice comes to nobody, the owners hear it. Each person can turn kinds off for themselves under My alerts.</p>
      {desk.length ? <p className="small muted">Office manager: {desk.map((u) => u.name).join(", ")}. Change it under People.</p> : <div className="note info"><Icon name="bell" small /><span>Nobody is marked as office manager yet. Until someone is, a client who has gone quiet goes to their preparer and anything else sent to the office manager goes to the owners. Mark someone under People.</span></div>}</div>
      <div className="tbl"><table style={{ minWidth: 0 }}><thead><tr><th>When</th><th>Who hears</th></tr></thead><tbody>{BARK_ROWS.map(([k, name_, note]) => <tr key={k}>
        <td><b>{name_}</b><div className="small muted">{note}</div></td>
        <td><select aria-label={"Who hears: " + name_} value={target(k)} onChange={(ev) => pick(k, ev.target.value)}>{TARGET.map(([v, l]) => <option key={v} value={v}>{l}</option>)}</select>
          {target(k) === "named_users" ? <><select aria-label={"Name a person for: " + name_} value="" onChange={(ev) => { if (ev.target.value) name(k, [...new Set([...ids(k), ev.target.value])]); }}><option value="">Add a person</option>{staff.filter((u) => !ids(k).includes(u.id)).map((u) => <option key={u.id} value={u.id}>{u.name}</option>)}</select>
            <div className="chips">{ids(k).map((id) => { const u = s.users.find((x: Row) => x.id === id); return u ? <span className="chip plain" key={id}>{u.name}<button className="chipx" aria-label={"Stop barking " + u.name + " for " + name_} onClick={() => name(k, ids(k).filter((x) => x !== id))}>×</button></span> : null; })}</div></> : null}</td></tr>)}</tbody></table></div></div>
    <div className="card pad col"><h2>Office hours for barks</h2><p className="small muted">Nobody is barked at outside these hours or at weekends. Anything that opens overnight is counted in the 7 am note instead. An item nobody has dealt with after one working day barks once more, to the owners.</p>
      <div className="row"><label className="f">From<select value={h.start} onChange={(ev) => hours(+ev.target.value, h.end)}>{Array.from({ length: 24 }, (_, i) => <option key={i} value={i}>{i}:00</option>)}</select></label><label className="f">Until<select value={h.end} onChange={(ev) => hours(h.start, +ev.target.value)}>{Array.from({ length: 24 }, (_, i) => <option key={i + 1} value={i + 1}>{i + 1}:00</option>)}</select></label></div></div>
  </div>;
}
// v2: an email-first firm has working days, not a daily sending window (docs/V2.md section 5).
